import json, html
from build_common import page, BASE
G=[
('guide-bulk-download-airtable-attachments.html','How to bulk download all Airtable attachments (free methods + one-click)',
 'Airtable has no "download all attachments" button. Here are the free ways to do it (CSV + script, Scripting extension, API) and a one-click option.',
 [('Why there is no button','Airtable lets you download one attachment at a time from an expanded record. Its own help center says there is no built-in bulk download in the interface and points to the Scripting extension instead (<a href="https://support.airtable.com/docs/attachment-field">source</a>). A "Download CSV" of a view gives you file names and <em>temporary</em> links, not the files.'),
  ('Free method 1: CSV export + a download script','<ol><li>Open the view, choose <b>Download CSV</b>.</li><li>Within about two hours, run a script that reads each URL from the attachment column and saves the file (wget/curl, PowerShell, or Python).</li><li>Prefix each filename with the record ID so two <code>invoice.pdf</code> files do not overwrite each other.</li></ol>Limits: links expire, attachment cells with several files need splitting, and you have to write or trust a script.'),
  ('Free method 2: Airtable Scripting extension','Airtable publishes a script (linked from the <a href="https://support.airtable.com/docs/attachment-field">attachment field article</a>) that generates download commands for a record, view or table. You then run those commands in a terminal before the links expire. Airtable itself notes the script may have limitations, so compare file counts afterwards.'),
  ('Free method 3: the Web API','Create a personal access token with <code>data.records:read</code>, call <a href="https://airtable.com/developers/web/api/list-records">List records</a> (100 records per page, follow <code>offset</code>), and download each attachment <code>url</code> right away. Respect the <a href="https://airtable.com/developers/web/api/rate-limits">rate limit</a> of 5 requests/second per base; after a 429 wait 30 seconds.'),
  ('One-click option: BaseDrop','BaseDrop is a Chrome extension that does method 3 for you: pick a base, table and view, and it fetches fresh links and writes the files into a ZIP (split at 500&nbsp;MB) plus an <code>index.csv</code>. It runs in your browser with your own token; files go from Airtable straight to your disk. The free version handles up to 50 files per export; Pro removes the limit and adds rename templates and whole-base export. <a href="install.html">Install</a>.')],
 [('Can Airtable export all attachments at once?','Not from the interface. CSV export only contains temporary links; you need a script, the API or an extension to fetch the files.'),
  ('Does it work with a filtered view?','Yes. The API accepts a view parameter, so only records visible in that view are exported, using the view\'s filters.')]),
('guide-airtable-attachment-urls-expire.html','Airtable attachment URLs expire: why, and how to fix it',
 'Airtable attachment links from CSV exports and the API stop working after a few hours. What changed, what still works, and how to keep permanent copies.',
 [('What is happening','Airtable serves files through expiring download URLs on <code>airtableusercontent.com</code>. Airtable says these links expire after a short time for security reasons, while the attachment viewer URL (opened inside Airtable) keeps working for collaborators (<a href="https://support.airtable.com/articles/9671148410-airtable-attachment-url-behavior">Airtable: attachment URL behavior</a>). Old CSV exports, emails and websites that embedded those links break.'),
  ('Fix 1: share inside Airtable','For colleagues who have base access, open the attachment, copy the viewer URL from the address bar. It does not expire while the attachment exists.'),
  ('Fix 2: copy files to permanent hosting with an automation','For websites and external partners, use an automation (Airtable automations with a script, Make or Zapier) that, when a record changes, downloads the file while the link is fresh and uploads it to Google Drive, S3 or Cloudinary, then writes the permanent link back to a URL field. Community examples: <a href="https://community.airtable.com/automations-8/how-to-solve-the-problem-of-airtable-attachment-urls-expiring-after-2-hours-45254">Cloudinary + Zapier/Make</a>.'),
  ('Fix 3: download the files themselves','If you just need the files (archive, hand-off, migration), fetch them in the same session you read the links. Any of the free methods in <a href="guide-bulk-download-airtable-attachments.html">this guide</a> work; BaseDrop does it in one pass, so a link never sits long enough to expire.')],
 [('How long do Airtable download links last?','Airtable describes them as expiring after a short time and changes may happen; plan for a few hours and never store them.'),
  ('Can I make a link permanent?','No. Store a copy of the file elsewhere and keep that URL instead.')]),
('guide-export-airtable-attachments-to-folders.html','Export Airtable attachments into folders (per record, client or project) for Drive or Dropbox',
 'How to export Airtable attachments organised into folders by record or by a field like Client, ready to drop into Google Drive or Dropbox.',
 [('The goal','A folder tree like <code>Client/Project/file.pdf</code> rather than one flat pile, so you can drag it into Google Drive or Dropbox and colleagues find files without Airtable.'),
  ('Free method: script with a folder column','Extend any CSV or API script so the save path is built from fields, e.g. <code>{Client}/{record id}/{filename}</code>. Strip characters that are illegal in file names (<code>/ \\ : * ? " &lt; &gt; |</code>) and handle empty values.'),
  ('Free method: automation straight to cloud storage','Make or Zapier can watch records and upload each attachment to a Drive/Dropbox folder named after a field. This is good for ongoing sync, but each file counts as operations on those platforms\' plans.'),
  ('With BaseDrop (Pro)','Set a folder template such as <code>{field:Client}/{field:Project}</code>; a "/" creates nested folders. Unzip the export into your synced Drive or Dropbox folder and the desktop client uploads it. BaseDrop does not connect to Drive or Dropbox accounts itself, so nothing else gets access to your cloud storage.')],
 [('Can I sync continuously?','BaseDrop exports on demand. For continuous sync use an automation tool.')]),
('guide-rename-airtable-attachments-on-download.html','Rename Airtable attachments when downloading (use field values as file names)',
 'Name downloaded Airtable files after field values such as invoice number or customer, without renaming them inside Airtable.',
 [('Why rename','Uploaded files are often <code>IMG_4821.jpg</code> or <code>scan (3).pdf</code>. A name like <code>INV-1042_Acme.pdf</code> is searchable once it leaves Airtable.'),
  ('Free method: rename inside Airtable','You can rename an attachment from the expanded record (hover the file, click the rename icon) as described in <a href="https://support.airtable.com/docs/attachment-field">Airtable\'s help</a>. Fine for a few files; slow for hundreds.'),
  ('Free method: rename in your download script','Build the target name from fields, e.g. <code>f"{fields[\'Invoice\']}_{n}{ext}"</code>, keep the original extension, and add a counter when a record has several files. Doing it in the script leaves Airtable untouched.'),
  ('With BaseDrop (Pro)','Use a filename template like <code>{field:Invoice}_{field:Customer}_{n}.{ext}</code>. Other tokens: <code>{filename}</code>, <code>{index}</code>, <code>{recordId}</code>, <code>{table}</code>. Duplicates get a suffix instead of overwriting, and <code>index.csv</code> maps each new name back to its record and original filename.')],
 [('Does renaming change files in Airtable?','No. Only the downloaded copies are renamed.')]),
('guide-airtable-backup-with-attachments.html','How to back up an Airtable base including attachment files',
 'A CSV backup of Airtable loses your files because attachment links expire. How to build a backup that keeps records and files together.',
 [('Why CSV alone is not a backup','CSV export keeps values but attachment cells become expiring links, so the files are gone once the links expire. Airtable snapshots restore inside Airtable only and are not an offline copy.'),
  ('Free method: CSV per table + files','<ol><li>Download CSV for every table (one view per table showing all fields).</li><li>Right away, download every attachment into folders named by record ID.</li><li>Keep both in the same dated folder, e.g. <code>2026-10-23/Orders.csv</code> and <code>2026-10-23/Orders/rec…/file.pdf</code>.</li></ol>The record ID is what lets you put files back on the right record later.'),
  ('Paid scheduled option','If you need hourly or daily automatic backups to cloud storage, hosted services exist, for example <a href="https://on2air.com/content/on2air-help-center/app-documentation/backups/what-we-backup/">On2Air Backups</a>. They need access to your Airtable account and your storage.'),
  ('With BaseDrop','Pro can export every table of a base in one run: files go into per-table folders and <code>index.csv</code> lists each file with its table, record ID, field and original name. Pair it with each table\'s CSV export for a complete manual backup. It runs on demand, not on a schedule.')],
 [('Is this a full backup?','No API-based export includes automations, interfaces or formulas\' definitions. It does keep record data and files.')]),
]
def faqld(q): return {"@type":"FAQPage","mainEntity":[{"@type":"Question","name":a,"acceptedAnswer":{"@type":"Answer","text":b}} for a,b in q]}
def build():
    links=''.join(f'<li><a href="{f}">{html.escape(t)}</a></li>' for f,t,*_ in G)
    for f,t,d,secs,faq in G:
        ld={"@context":"https://schema.org","@graph":[{"@type":"Article","headline":t,"description":d,"dateModified":"2026-10-23","author":{"@type":"Organization","name":"SteadyFlowSheets"},"mainEntityOfPage":BASE+f},faqld(faq)]}
        body=f'<article><h1>{html.escape(t)}</h1><p class="lead">{html.escape(d)}</p>'+''.join(f'<h2>{h}</h2><p>{c}</p>' for h,c in secs)+'<h2>FAQ</h2>'+''.join(f'<details><summary>{html.escape(a)}</summary><p>{html.escape(b)}</p></details>' for a,b in faq)+f'<h2>More guides</h2><ul>{links}</ul><p><small>Updated 2026-10-23. Airtable is a trademark of Formagrid Inc.; BaseDrop is not affiliated with Airtable.</small></p></article>'
        page(f,t,d,body,'<script type="application/ld+json">'+json.dumps(ld)+'</script>')
    open('guides.html','w')
    page('guides.html','Airtable attachment guides','Free and one-click ways to download, rename, organise and back up Airtable attachments.',f'<h1>Guides</h1><ul>{links}</ul>')
    return [f for f,*_ in G]+['guides.html']
